import { lazy } from 'react';
import { BarChart3 as IcBarChart3, FileText as IcFileText, FormInput as IcFormInput, Scale as IcScale, Workflow as IcWorkflow } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Analysis & Automation — hub page for the CRM menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 4 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'CRMInsights'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const WonLostLeads = lazy(() => import('./WonLostLeads'));
const WebLeadForms = lazy(() => import('./WebLeadForms'));
const CRMReports = lazy(() => import('./CRMReports'));
const PipelineAutomation = lazy(() => import('./PipelineAutomation'));

export const TABS = [
  { id: 'wonlost', label: 'Won / Lost Leads', icon: IcScale, page: 'WonLostLeads', Component: WonLostLeads },
  { id: 'forms', label: 'Web-to-Lead Forms', icon: IcFormInput, page: 'WebLeadForms', Component: WebLeadForms },
  { id: 'reports', label: 'Reports', icon: IcFileText, page: 'CRMReports', Component: CRMReports },
  { id: 'automation', label: 'Pipeline Automation', icon: IcWorkflow, page: 'PipelineAutomation', Component: PipelineAutomation },
];

export default function CRMInsights({ setPage }) {
  return (
    <TabHub
      icon={IcBarChart3}
      eyebrow="CRM"
      title="Analysis & Automation"
      subtitle="Won/lost analysis, inbound web forms, CRM reports and pipeline automation"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
